'use strict';

const state = { csrf: '', user: null, view: 'dashboard', sites: [], groups: [], nodes: [], ads: [], siteLocalAds: [], adPolicies: [], adEdgeProfiles: [], jobsTimer: null };
const titles = { dashboard: '运行概览', sites: '导航站', groups: '站点分组', nodes: '节点管理', ads: '广告管理', publish: '永久发布页', settings: '平台与告警设置', jobs: '任务中心', audit: '审计日志', security: '安全设置' };
const adSlotLabels = { banner: '横幅', icon: '图标', top_float: '顶部代码', bottom_float: '底部代码', icon_float: '图标代码' };
const adPolicyLabels = { central_only: '仅中央', central_first: '中央优先', mixed: '混合排序', local_only: '仅本地' };
const $ = selector => document.querySelector(selector);

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
}

function formatTime(value) {
  if (!value) return '尚未连接';
  return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date(value));
}

function safeUrl(value) {
  try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) ? url.href : ''; } catch { return ''; }
}

function toast(message) {
  const element = $('#toast'); element.textContent = message; element.hidden = false;
  clearTimeout(toast.timer); toast.timer = setTimeout(() => { element.hidden = true; }, 4000);
}

async function api(path, options = {}) {
  const headers = { Accept: 'application/json', ...(options.headers || {}) };
  if (options.body && typeof options.body !== 'string') { headers['content-type'] = 'application/json'; options.body = JSON.stringify(options.body); }
  if (state.csrf && !['GET', 'HEAD'].includes(String(options.method || 'GET').toUpperCase())) headers['x-csrf-token'] = state.csrf;
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers });
  const payload = response.status === 204 ? null : await response.json().catch(() => null);
  if (response.status === 401) { showLogin(); throw new Error(payload?.message || '登录已过期'); }
  if (!response.ok) throw new Error(payload?.message || `请求失败（${response.status}）`);
  return payload?.data;
}

function showLogin() { $('#loginView').hidden = false; $('#appShell').hidden = true; state.csrf = ''; }
function showApp() { $('#loginView').hidden = true; $('#appShell').hidden = false; $('#currentUser').textContent = state.user.username; }

function pageHeader(_title, description, action = '') {
  return `<div class="page-header"><p>${escapeHtml(description)}</p><div class="actions">${action}</div></div>`;
}
function badge(value) { const text = String(value || '未知'); return `<span class="badge ${escapeHtml(text)}">${escapeHtml(text)}</span>`; }
function publishPlatformBadge(label,result){const status=result?.status||'pending',text=status==='succeeded'?'已发布':status==='failed'?'失败':status==='running'?'发布中':status==='skipped'?'未启用':'待发布';return `<span class="badge ${escapeHtml(status)}">${escapeHtml(label)}：${text}</span>`;}
function jobStatusBadge(status){const labels={queued:'排队中',running:'执行中',succeeded:'已完成',failed:'执行失败',cancelled:'已取消'};return `<span class="badge ${escapeHtml(status||'pending')}">${escapeHtml(labels[status]||'未知状态')}</span>`;}
function empty(text) { return `<div class="empty">${escapeHtml(text)}</div>`; }
function link(value, label = value) { const href = safeUrl(value); return href ? `<a class="url" href="${escapeHtml(href)}" target="_blank" rel="noopener">${escapeHtml(label)}</a>` : escapeHtml(label || '—'); }

async function ensureTaxonomy() {
  if (!state.sites.length) state.sites = await api('/api/admin/sites');
  if (!state.groups.length) state.groups = await api('/api/admin/groups');
}

async function renderDashboard() {
  const data = await api('/api/admin/dashboard'); const c = data.counts;
  $('#content').innerHTML = `${pageHeader('全局运行状态','不同云厂商上的导航站，通过站点主动连接统一受控。')}
    <div class="metric-grid"><article class="metric"><span>登记站点</span><strong>${c.sites}</strong></article><article class="metric"><span>在线站点</span><strong>${c.online_sites}</strong></article><article class="metric"><span>启用节点</span><strong>${c.nodes}</strong></article><article class="metric"><span>中央广告</span><strong>${c.ads}</strong></article><article class="metric"><span>待执行任务</span><strong>${c.active_jobs}</strong></article></div>
    <section class="panel"><div class="panel-header"><h3>最近连接的站点</h3><button class="secondary" data-view-jump="sites">管理站点</button></div>${data.recent_sites.length ? `<div class="table-wrap"><table><thead><tr><th>站点</th><th>状态</th><th>Agent</th><th>最后心跳</th></tr></thead><tbody>${data.recent_sites.map(site=>`<tr><td><strong>${escapeHtml(site.name)}</strong><br>${link(site.public_url)}</td><td>${badge(site.status)}</td><td>${escapeHtml(site.agent_version||'未上报')}</td><td>${formatTime(site.last_seen_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('尚未登记导航站')}</section>`;
}

async function renderSites() {
  state.sites = await api('/api/admin/sites');
  $('#content').innerHTML = `${pageHeader('导航站','登记不同域名和服务器上的导航站，并通过一次性票据进入后台。','<button class="primary" data-action="site-new">新增导航站</button>')}
    <section class="panel">${state.sites.length ? `<div class="table-wrap"><table><thead><tr><th>站点</th><th>连接</th><th>配置版本</th><th>凭据</th><th>操作</th></tr></thead><tbody>${state.sites.map(site=>`<tr><td><strong>${escapeHtml(site.name)}</strong><br>${link(site.public_url,site.slug)}</td><td>${badge(site.status)}<br><span class="muted">${formatTime(site.last_seen_at)}</span></td><td>N ${site.nodes_revision} · A ${site.ads_revision} · P ${site.publish_revision}</td><td>尾号 ${escapeHtml(site.secret_hint)}</td><td><div class="row-actions"><button data-action="site-enter" data-id="${site.id}">进入后台</button><button data-action="site-policy" data-id="${site.id}">广告策略</button><button data-action="site-edit" data-id="${site.id}">编辑</button><button data-action="site-rotate" data-id="${site.id}">换密钥</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚未登记站点，先新增一个测试站点')}</section>`;
}

async function renderGroups() {
  await ensureTaxonomy(); state.groups = await api('/api/admin/groups');
  $('#content').innerHTML = `${pageHeader('站点分组','用一个分组给多个导航站统一下发节点或广告。','<button class="primary" data-action="group-new">新增分组</button>')}<div class="card-list">${state.groups.length?state.groups.map(group=>`<article class="item-card"><h3>${escapeHtml(group.name)}</h3><p class="muted">${escapeHtml(group.slug)}</p><div class="meta"><span class="badge">${group.site_ids.length} 个站点</span></div><footer><button class="secondary" data-action="group-edit" data-id="${group.id}">编辑成员</button></footer></article>`).join(''):empty('尚未创建站点分组')}</div>`;
}

function nodeScopeText(node) {
  if (node.scope_mode === 'global') return '全部启用站点';
  const siteNames = new Map(state.sites.map(item => [Number(item.id), item.name]));
  const groupNames = new Map(state.groups.map(item => [Number(item.id), item.name]));
  const siteIds = Array.isArray(node.site_ids) ? node.site_ids : [];
  const groupIds = Array.isArray(node.group_ids) ? node.group_ids : [];
  const parts = [];
  if (siteIds.length) parts.push(`站点：${siteIds.map(id => siteNames.get(Number(id)) || `#${id}`).join('、')}`);
  if (groupIds.length) parts.push(`分组：${groupIds.map(id => groupNames.get(Number(id)) || `#${id}`).join('、')}`);
  return parts.join('；') || '未指定范围';
}

function nodeSyncCounts() {
  const enabledSites = state.sites.filter(site => site.enabled !== false);
  const synced = enabledSites.filter(site => String(site.applied_revision || '').split('-')[0] === String(site.nodes_revision)).length;
  return { total: enabledSites.length, synced, pending: enabledSites.length - synced };
}

async function renderNodes() {
  await ensureTaxonomy(); state.nodes = await api('/api/admin/nodes');
  const sync = nodeSyncCounts();
  $('#content').innerHTML = `${pageHeader('统一节点管理','节点由总后台统一维护，并按全部站点、指定站点或站点分组下发完整快照。','<button class="primary" data-action="node-new">新增节点</button>')}
    <div class="metric-grid"><article class="metric"><span>节点总数</span><strong>${state.nodes.length}</strong></article><article class="metric"><span>启用节点</span><strong>${state.nodes.filter(node=>node.enabled).length}</strong></article><article class="metric"><span>已同步站点</span><strong>${sync.synced}/${sync.total}</strong></article><article class="metric"><span>等待同步</span><strong>${sync.pending}</strong></article></div>
    <section class="panel">${state.nodes.length?`<div class="table-wrap"><table><thead><tr><th>节点</th><th>地址</th><th>投放范围</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.nodes.map(node=>`<tr><td><strong>${escapeHtml(node.speed_name)}</strong><br><span class="muted">${escapeHtml(node.partner_name)}</span></td><td>${link(node.url)}</td><td class="scope-cell" title="${escapeHtml(nodeScopeText(node))}">${escapeHtml(nodeScopeText(node))}</td><td>${Number(node.sort_order||0)}</td><td><span class="badge ${node.enabled?'enabled':'disabled'}">${node.enabled?'已启用':'已停用'}</span></td><td><div class="row-actions"><button data-action="node-edit" data-id="${node.id}">编辑</button><button data-action="node-delete" data-id="${node.id}">删除</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚未配置中央节点')}</section>`;
}

function adScopeText(ad) {
  if (ad.scope_mode === 'global') return '全部启用站点';
  const siteNames = new Map(state.sites.map(item => [Number(item.id), item.name]));
  const groupNames = new Map(state.groups.map(item => [Number(item.id), item.name]));
  const siteIds = Array.isArray(ad.site_ids) ? ad.site_ids : [];
  const groupIds = Array.isArray(ad.group_ids) ? ad.group_ids : [];
  const parts = [];
  if (siteIds.length) parts.push(`站点：${siteIds.map(id => siteNames.get(Number(id)) || `#${id}`).join('、')}`);
  if (groupIds.length) parts.push(`分组：${groupIds.map(id => groupNames.get(Number(id)) || `#${id}`).join('、')}`);
  return parts.join('；') || '未指定范围';
}

function policySummary(items = []) {
  const policies = new Map(items.map(item => [item.slot, item.policy]));
  return Object.keys(adSlotLabels).map(slot => {
    const policy = policies.get(slot) || 'central_first';
    return `<span class="policy-chip"><span>${escapeHtml(adSlotLabels[slot])}</span><strong>${escapeHtml(adPolicyLabels[policy])}</strong></span>`;
  }).join('');
}

function adSiteSyncBadge(site) {
  if (site.enabled === false) return '<span class="badge disabled">站点已停用</span>';
  const applied = String(site.applied_revision || '').split('-')[1];
  const synced = applied === String(site.ads_revision);
  return `<span class="badge ${synced?'enabled':'pending'}">${synced?'已同步':`待同步（A${escapeHtml(site.ads_revision)}）`}</span>`;
}

async function previewSiteAds(siteId) {
  const data = await api(`/api/admin/sites/${siteId}/ads`);
  openModal(`${data.site.name}·广告快照`, `<p class="muted">该快照是导航站下次同步会收到的中央广告，不包含该站自己维护的本地广告。</p><div class="policy-list">${policySummary(data.policies)}</div>${data.ads.length?`<div class="table-wrap"><table><thead><tr><th>广告</th><th>广告位</th><th>类型</th><th>优先级</th></tr></thead><tbody>${data.ads.map(ad=>`<tr><td><strong>${escapeHtml(ad.title)}</strong><br><span class="muted">${escapeHtml(ad.namespace)}</span></td><td>${escapeHtml(adSlotLabels[ad.ad_position]||ad.ad_position)}</td><td>${ad.ad_type==='code'?'联盟代码':'普通图片'}</td><td>${Number(ad.priority||0)}</td></tr>`).join('')}</tbody></table></div>`:empty('该站当前没有命中任何中央广告')}<div class="modal-actions"><button class="primary" value="save">关闭</button></div>`, async()=>({message:'已关闭快照',refresh:false}), 'EFFECTIVE SNAPSHOT');
}

async function publishHistory(siteId) {
  const data=await api(`/api/admin/sites/${siteId}/publish/history`);
  const rows=data.jobs.map(job=>{const platforms=job.result?.platforms||{},manifest=job.result?.build?.manifest;return `<tr><td>#${job.id}<br><span class="muted">${formatTime(job.created_at)}</span></td><td>${jobStatusBadge(job.status)}</td><td><div class="meta">${publishPlatformBadge('CF',platforms.cloudflare)}${publishPlatformBadge('GH',platforms.github)}${platforms.npm?publishPlatformBadge('npm',platforms.npm):''}</div></td><td>${manifest?.sha256?`<span class="code-preview" title="${escapeHtml(manifest.sha256)}">${escapeHtml(manifest.sha256.slice(0,12))}…</span>`:'—'}</td><td>${Number(job.attempts||0)}/${Number(job.max_attempts||0)}</td><td>${job.status==='failed'?`<button type="button" class="secondary" data-action="publish-retry" data-id="${job.id}">重试</button>`:'—'}</td></tr>${job.last_error?`<tr class="history-error"><td colspan="6"><span>失败原因：</span>${escapeHtml(job.last_error)}</td></tr>`:''}`;}).join('');
  openModal(`${data.site.name}·发布历史`,`${data.jobs.length?`<div class="table-wrap"><table><thead><tr><th>任务 / 创建时间</th><th>状态</th><th>平台结果</th><th>内容摘要</th><th>尝试</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('该站点还没有发布记录')}<div class="modal-actions"><button class="primary" value="save">关闭</button></div>`,async()=>({message:'已关闭发布历史',refresh:false}),'DEPLOYMENT HISTORY');
}

async function renderAds() {
  await ensureTaxonomy(); [state.ads,state.siteLocalAds,state.adPolicies,state.adEdgeProfiles] = await Promise.all([api('/api/admin/ads'),api('/api/admin/site-local-ads'),api('/api/admin/ad-policies'),api('/api/admin/ad-edge-profiles')]);
  const enabledSites=state.adPolicies.filter(site=>site.enabled!==false);const synced=enabledSites.filter(site=>String(site.applied_revision||'').split('-')[1]===String(site.ads_revision)).length;
  $('#content').innerHTML = `${pageHeader('广告混合管理','代码广告统一由分配给导航站的广告 API 加载；支持主页面执行与沙箱 iframe。','<button class="primary" data-action="ad-new">新增中央广告</button>')}
    <div class="metric-grid"><article class="metric"><span>中央广告</span><strong>${state.ads.length}</strong></article><article class="metric"><span>启用广告</span><strong>${state.ads.filter(ad=>ad.enabled).length}</strong></article><article class="metric"><span>代码广告</span><strong>${state.ads.filter(ad=>ad.ad_type==='code').length}</strong></article><article class="metric"><span>已同步站点</span><strong>${synced}/${enabledSites.length}</strong></article></div>
    <section class="panel"><div class="panel-header"><div><h3>中央广告</h3><p class="muted">排序数值越大越靠前；定向范围可为站点、分组或两者并集。</p></div></div>${state.ads.length?`<div class="table-wrap"><table><thead><tr><th>广告</th><th>类型/位置</th><th>投放范围</th><th>优先级</th><th>完整性</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.ads.map(ad=>`<tr><td><strong>${escapeHtml(ad.title)}</strong><br><span class="muted">${escapeHtml(ad.namespace)}</span></td><td>${ad.ad_type==='code'?'联盟代码':'普通图片'} · ${escapeHtml(adSlotLabels[ad.ad_position]||ad.ad_position)}</td><td class="scope-cell" title="${escapeHtml(adScopeText(ad))}">${escapeHtml(adScopeText(ad))}</td><td>${Number(ad.priority||0)}</td><td class="code-preview" title="${escapeHtml(ad.integrity_sha256)}">${escapeHtml(ad.integrity_sha256.slice(0,14))}…</td><td><span class="badge ${ad.enabled?'enabled':'disabled'}">${ad.enabled?'已启用':'已停用'}</span></td><td><div class="row-actions"><button data-action="ad-edit" data-id="${ad.id}">编辑</button><button data-action="ad-delete" data-id="${ad.id}">删除</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚未配置中央广告')}</section>
    <section class="panel"><div class="panel-header"><div><h3>导航站本地广告</h3><p class="muted">各导航站可单独配置后回传总后台。普通图文只同步配置并由导航站直接渲染；代码正文不在列表回显，运行时统一经独立广告 API 加载。</p></div></div>${state.siteLocalAds.length?`<div class="table-wrap"><table><thead><tr><th>导航站 / 广告</th><th>类型 / 位置</th><th>显示与加载</th><th>排序</th><th>状态</th><th>最近同步</th></tr></thead><tbody>${state.siteLocalAds.map(ad=>`<tr><td><strong>${escapeHtml(ad.site_name)} · ${escapeHtml(ad.title||`本地广告 #${ad.local_ad_id}`)}</strong><br><span class="muted">${escapeHtml(ad.slug)} / #${Number(ad.local_ad_id)}</span></td><td>${ad.ad_type==='code'?'联盟代码':'普通图文'} · ${escapeHtml(adSlotLabels[ad.ad_position]||ad.ad_position)}</td><td>${ad.ad_type==='code'?(ad.render_mode==='sandbox'?'沙箱 iframe · 系统定位':'主页面执行 · 代码定位'):`${escapeHtml(ad.platform||'all')} · 本站直接输出`}</td><td>${Number(ad.priority||0)}</td><td><span class="badge ${ad.enabled?'enabled':'disabled'}">${ad.enabled?'已启用':'已停用'}</span></td><td>${formatTime(ad.updated_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无导航站本地广告同步记录')}</section>
    <section class="panel"><div class="panel-header"><div><h3>广告 API 管理</h3><p class="muted">独立域名统一承载 Direct 代码分发和 Sandbox iframe；站点分配优先于分组，分组优先于默认 API。</p></div><button class="primary" data-action="ad-edge-new">新建广告 API</button></div>${state.adEdgeProfiles.length?`<div class="table-wrap"><table><thead><tr><th>名称</th><th>API 域名 / Worker</th><th>分配</th><th>版本</th><th>健康</th><th>操作</th></tr></thead><tbody>${state.adEdgeProfiles.map(profile=>`<tr><td><strong>${escapeHtml(profile.name)}</strong>${profile.is_default?'<br><span class="badge enabled">默认中央 API</span>':''}</td><td>${link(`https://${profile.hostname}`,profile.hostname)}<br><span class="muted">${escapeHtml(profile.worker_name)}</span></td><td>${profile.is_default?'全部未单独指定的站点':`${profile.site_ids.length} 个站点 · ${profile.group_ids.length} 个分组`}</td><td>${escapeHtml(profile.worker_version||'尚未部署')}</td><td><span class="badge ${profile.health_status==='healthy'?'enabled':profile.health_status==='error'?'failed':'pending'}">${escapeHtml(profile.health_status||'unknown')}</span>${profile.last_error?`<br><span class="muted">${escapeHtml(profile.last_error)}</span>`:''}</td><td><div class="row-actions"><button data-action="ad-edge-edit" data-id="${profile.id}">编辑分配</button><button data-action="ad-edge-deploy" data-id="${profile.id}">部署/更新</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚未创建广告 API；创建默认中央 API 后代码广告才会开始下发')}</section>
    <section class="panel"><div class="panel-header"><div><h3>各站混合策略</h3><p class="muted">每个广告位独立决定中央广告与本地广告的关系。</p></div></div>${state.adPolicies.length?`<div class="table-wrap"><table><thead><tr><th>导航站</th><th>五个广告位策略</th><th>同步状态</th><th>操作</th></tr></thead><tbody>${state.adPolicies.map(site=>`<tr><td><strong>${escapeHtml(site.name)}</strong><br><span class="muted">${escapeHtml(site.slug)}</span></td><td><div class="policy-list">${policySummary(site.policies)}</div></td><td>${adSiteSyncBadge(site)}</td><td><div class="row-actions"><button data-action="ad-site-policy" data-id="${site.id}">编辑策略</button><button data-action="ad-site-preview" data-id="${site.id}">查看快照</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('尚未登记导航站')}</section>`;
}

function publishState(site,config){
  const modes=config.platform_accounts||{};const gh=modes.github?.mode!=='disabled',cf=modes.cloudflare?.mode!=='disabled',npm=modes.npm?.mode!=='disabled',notion=modes.notion?.mode!=='disabled';
  const ready=Boolean((gh||cf||npm||(notion&&config.notion_sync_enabled))&&(!gh||(config.github_pages_url&&config.github_repo))&&(!cf||(config.permanent_url&&config.cloudflare_project))&&(!npm||(gh&&config.npm_package_name))&&(!(notion&&config.notion_sync_enabled)||(config.notion_page_id&&config.notion_public_url)));
  const active=['queued','running'].includes(config.deployment_status);
  const built=config.deployment_result?.build;
  const current=Boolean(built&&Number(built.publish_revision)===Number(site.publish_revision)&&Number(built.nodes_revision)===Number(site.nodes_revision));
  if(!ready)return{ready,active,current,label:'配置未完成',className:'pending'};
  if(active)return{ready,active,current,label:config.deployment_status==='queued'?'等待发布':'正在发布',className:'running'};
  if(config.deployment_status==='failed')return{ready,active,current,label:'发布失败',className:'failed'};
  if(config.deployment_status==='succeeded'&&current)return{ready,active,current,label:'已是最新',className:'succeeded'};
  return{ready,active,current,label:'有更新待发布',className:'stale'};
}
function publishDeliveryPending(site){const applied=String(site.applied_revision||'').split('-');return site.enabled!==false&&String(applied[2]||'')!==String(site.publish_revision||'');}

function publishAddress(label,value){const href=safeUrl(value);return `<div class="publish-address"><span>${escapeHtml(label)}</span><div>${link(value,value||'尚未配置')} ${href?`<div class="publish-address-actions"><a class="publish-open" href="${escapeHtml(href)}" target="_blank" rel="noopener">打开页面</a><button type="button" data-copy="${escapeHtml(href)}">复制地址</button></div>`:''}</div></div>`;}
function publishDistributionLine(item){return `<span class="badge">${escapeHtml(item.label||item.provider)} · 包分发</span>`;}
function npmInstructionRows(guide={}){return `<dl class="instruction-list"><div><dt>GitHub 用户或组织</dt><dd><code>${escapeHtml(guide.organization||'—')}</code></dd></div><div><dt>仓库名称</dt><dd><code>${escapeHtml(guide.repository||'—')}</code></dd></div><div><dt>Workflow 文件名</dt><dd><code>${escapeHtml(guide.workflow_file||'publish-npm.yml')}</code></dd></div><div><dt>Environment</dt><dd><code>${escapeHtml(guide.environment||'留空')}</code></dd></div><div><dt>Allowed actions</dt><dd><strong>允许直接 ${escapeHtml(guide.allowed_action||'npm publish')}</strong></dd></div></dl>`;}
function npmBootstrapPanel(site,config){
  const state=config.npm_bootstrap;
  if(!config.npm_enabled||!state)return'';
  if(state.status==='oidc_verified'){
    return `<div class="setup-callout setup-callout--success"><div><strong>npm OIDC 自动发布已验证</strong><p>首次创建与 Trusted Publisher 配置均已完成，后续版本无需 npm Token。</p></div><span class="badge succeeded">验证于 ${escapeHtml(formatTime(state.oidc_verified_at))}</span></div>`;
  }
  if(state.status==='published'){
    const guide=state.instructions||{};
    const settingsUrl=safeUrl(guide.package_settings_url);
    return `<section class="setup-callout setup-callout--warning" aria-label="npm Trusted Publisher 待配置"><div><strong>首次发布成功，还需配置 Trusted Publisher</strong><p>进入 npm 包设置 → Trusted publishing → GitHub Actions，并严格填写以下内容。完成前请不要撤销当前提示。</p>${npmInstructionRows(guide)}${state.last_error?`<p class="error-text">最近错误：${escapeHtml(state.last_error)}</p>`:''}</div><div class="setup-actions">${settingsUrl?`<a class="secondary button-link" href="${escapeHtml(settingsUrl)}" target="_blank" rel="noopener">打开 npm 包设置</a>`:''}<button class="primary" data-action="npm-oidc-verify" data-id="${site.id}">已完成设置，验证 OIDC</button></div></section>`;
  }
  if(state.eligible){
    return `<section class="setup-callout setup-callout--warning"><div><strong>这是新 npm 包，需要完成一次首次发布</strong><p>使用有效期尽可能短、允许绕过 2FA 且限制为服务器出口 IP 的 Granular Token。Token 只在当前请求内使用，不保存到数据库或任务队列。</p>${state.last_error?`<p class="error-text">最近错误：${escapeHtml(state.last_error)}</p>`:''}</div><button class="primary" data-action="npm-bootstrap" data-id="${site.id}" data-package="${escapeHtml(config.npm_package_name)}">服务器首次发布</button></section>`;
  }
  return `<div class="setup-callout"><div><strong>npm 首次发布尚未准备</strong><p>先执行一次正常发布任务；当 GitHub 已生成发布包而 npm 因新包未建立而失败后，这里会出现“服务器首次发布”。</p></div></div>`;
}

async function renderPublish() {
  state.sites = await api('/api/admin/sites');
  const configs = await Promise.all(state.sites.map(site=>api(`/api/admin/sites/${site.id}/publish`).then(config=>({site,config,state:publishState(site,config),deliveryPending:publishDeliveryPending(site)}))));
  const counts={ready:configs.filter(item=>item.state.ready).length,current:configs.filter(item=>item.state.label==='已是最新').length,pending:configs.filter(item=>['有更新待发布','等待发布','正在发布'].includes(item.state.label)).length,delivering:configs.filter(item=>item.deliveryPending).length,failed:configs.filter(item=>item.state.label==='发布失败').length};
  $('#content').innerHTML = `${pageHeader('永久发布页','集中管理每个导航站在 Cloudflare、GitHub Pages、npm 与 Notion 上的永久发布页。Notion 可仅展示公开页，也可启用自动同步。')}
    <div class="metric-grid publish-metrics"><article class="metric"><span>站点总数</span><strong>${configs.length}</strong></article><article class="metric"><span>配置完整</span><strong>${counts.ready}</strong></article><article class="metric"><span>已是最新</span><strong>${counts.current}</strong></article><article class="metric"><span>待发布 / 发布中</span><strong>${counts.pending}</strong></article><article class="metric"><span>下发中</span><strong>${counts.delivering}</strong></article><article class="metric"><span>需要处理</span><strong>${counts.failed}</strong></article></div>
    <section class="panel"><div class="panel-header"><div><h3>站点发布流水线</h3><p class="muted">每个平台明确选择全局账号、本站独立账号或停用；系统不会在凭据缺失时自动换用其他账号。</p></div></div>${configs.length?`<div class="publish-list">${configs.map(({site,config,state:status,deliveryPending})=>{const platforms=config.deployment_result?.platforms||{},accounts=config.platform_accounts||{};const npmEntries=(config.npm_page_urls||[]).filter(item=>item.page_entry).map(item=>publishAddress(`${item.entry_primary?'主网页入口 · ':''}npm · ${item.label}`,item.url)).join('');const npmDistribution=(config.npm_page_urls||[]).filter(item=>!item.page_entry).map(publishDistributionLine).join('');const notionStatus=config.notion_sync_enabled?publishPlatformBadge('Notion',platforms.notion):config.notion_enabled?'<span class="badge pending">Notion：仅公开页</span>':'';const mode=name=>accounts[name]?.mode==='global'?'全局账号':accounts[name]?.mode==='site'?'本站账号':'未启用';return `<article class="publish-row"><div class="publish-site"><div><h3>${escapeHtml(site.name)}</h3><p>${escapeHtml(site.slug)} · CF ${mode('cloudflare')} · GH ${mode('github')} · npm ${mode('npm')} · Notion ${mode('notion')}</p></div><div class="meta"><span class="badge ${status.className}">${status.label}</span>${deliveryPending?'<span class="badge running">下发中</span>':''}</div></div><div class="publish-addresses">${accounts.cloudflare?.mode!=='disabled'?publishAddress('Cloudflare 自定义永久域名',config.permanent_url):''}${accounts.github?.mode!=='disabled'?publishAddress('GitHub Pages 完整发布页',config.github_pages_url):''}${config.notion_enabled?publishAddress('Notion 公告发布页',config.notion_public_url):''}${config.npm_enabled?npmEntries:''}</div>${npmDistribution?`<div class="publish-platforms"><span class="publish-time">npm 包分发：</span>${npmDistribution}</div>`:''}<div class="publish-platforms">${publishPlatformBadge('Cloudflare',platforms.cloudflare)}${publishPlatformBadge('GitHub Pages',platforms.github)}${config.npm_enabled?publishPlatformBadge('npm',platforms.npm):''}${notionStatus}<span class="publish-time">最近发布：${formatTime(config.deployed_at||config.deployment_created_at)}</span></div>${npmBootstrapPanel(site,config)}${config.notion_last_error?`<p class="error-text" role="status">Notion 最近错误：${escapeHtml(config.notion_last_error)}</p>`:''}${config.deployment_error?`<p class="error-text" role="status">最近错误：${escapeHtml(config.deployment_error)}</p>`:''}<footer><button class="secondary" data-action="publish-preview" data-id="${site.id}">预览完整页面</button><button class="secondary" data-action="publish-history" data-id="${site.id}">发布历史</button><button class="secondary" data-action="publish-edit" data-id="${site.id}">配置发布页</button>${['cloudflare','github','npm','notion'].filter(name=>accounts[name]?.mode!=='disabled').map(name=>`<button class="secondary" data-action="publish-platform-test" data-provider="${name}" data-id="${site.id}">测试 ${name}</button>`).join('')}${config.deployment_status==='failed'?`<button class="secondary" data-action="publish-retry" data-id="${config.deployment_job_id}">重试失败平台</button>`:''}<button class="primary" data-action="publish-queue" data-id="${site.id}" ${status.ready&&!status.active?'':'disabled'}>${status.active?'发布进行中':'发布已启用平台'}</button></footer></article>`;}).join('')}</div>`:empty('请先登记导航站')}</section>`;
}

function platformSecretStatus(value) { return value?.configured ? '<span class="badge succeeded">凭据已配置</span>' : '<span class="badge pending">等待配置</span>'; }
const npmPageEntryProviders=new Set(['unpkg','esm']);
function npmEntryPrimary(selected=[],primary=''){const entries=selected.filter(item=>npmPageEntryProviders.has(item));return entries.includes(primary)?primary:(entries[0]||'');}
function platformCdnChoices(selected=[], primary='', disabled=false) { const resolvedPrimary=npmEntryPrimary(selected,primary);const providers=[['npmmirror','中国大陆 npm 镜像 · npmmirror','package'],['jsdelivr','静态文件分发 · jsDelivr','package'],['unpkg','网页入口 · UNPKG','page'],['esm','网页入口 · esm.sh','page']]; return `<div class="cdn-choice-list">${providers.map(([value,label,role])=>`<label class="checkbox-line"><input type="checkbox" name="npm_lines" value="${value}" ${selected.includes(value)?'checked':''} ${disabled?'disabled':''}>${label}<span class="cdn-primary">${role==='page'?`<input type="radio" name="npm_primary" value="${value}" ${resolvedPrimary===value?'checked':''} ${disabled?'disabled':''}>主网页入口`:'包分发'}</span></label>`).join('')}</div>`; }
function platformCdnOverview(selected=[], primary='') {
  const providers=[
    ['npmmirror','包分发','npmmirror'],
    ['jsdelivr','包分发','jsDelivr'],
    ['unpkg','网页入口','UNPKG'],
    ['esm','网页入口','esm.sh']
  ];
  const resolvedPrimary=npmEntryPrimary(selected,primary);
  return `<div class="cdn-route-grid">${providers.map(([value,role,label])=>{
    const enabled=selected.includes(value);
    return `<article class="cdn-route ${enabled?'is-enabled':''}"><div class="cdn-route-copy"><span>${escapeHtml(role)}</span><strong>${escapeHtml(label)}</strong></div><div class="cdn-route-state">${enabled?'<span class="badge succeeded">已启用</span>':'<span class="badge">未启用</span>'}${resolvedPrimary===value?'<span class="badge primary-badge">主网页入口</span>':''}</div></article>`;
  }).join('')}</div>`;
}

async function renderSettings() {
  const [settings,siteAccounts]=await Promise.all([api('/api/admin/platform-settings'),api('/api/admin/platform-settings/site-accounts')]);
  state.sites=siteAccounts.map(item=>item.site);
  const card=(eyebrow,title,description,status,provider)=>`<article class="setting-card"><div class="setting-card-copy"><span class="setting-kicker">${eyebrow}</span><h3>${title}</h3><p>${description}</p></div><div class="setting-card-footer">${status}<button class="secondary" data-action="platform-test" data-provider="${provider}">测试连接</button></div></article>`;
  const configured=account=>account?.credential?.configured;
  const siteCard=item=>{const platforms=item.platforms||{},status=(name,label,ready)=>`<span class="badge ${ready?'succeeded':'pending'}">${label}：${ready?'已配置':'未配置'}</span>`;return `<article class="site-account-card"><header><div><span class="setting-kicker">本站独立账号</span><h3>${escapeHtml(item.site.name)}</h3><p>${escapeHtml(item.site.slug)}</p></div><button class="secondary" data-action="site-platform-edit" data-id="${item.site.id}">编辑独立账号</button></header><div class="site-account-status">${status('github','GitHub',configured(platforms.github))}${status('cloudflare','Cloudflare',configured(platforms.cloudflare)&&Boolean(platforms.cloudflare?.settings?.account_id))}${status('npm','npm',Boolean(platforms.npm?.settings?.username)&&npmEntryPrimary(platforms.npm?.settings?.lines,platforms.npm?.settings?.primary))}${status('notion','Notion',configured(platforms.notion))}</div><footer>${['github','cloudflare','npm','notion'].map(name=>`<button class="ghost" data-action="site-platform-test" data-id="${item.site.id}" data-provider="${name}">测试 ${name}</button>`).join('')}</footer></article>`;};
  $('#content').innerHTML=`${pageHeader('平台与告警设置','统一管理全局发布账号、各导航站独立发布账号和系统级告警。永久发布页只负责选择账号来源。','<button class="primary" data-action="platform-edit">编辑全局设置</button>')}
    <section class="panel settings-panel"><div class="panel-header"><div><h3>全局发布账号</h3><p class="muted">只有站点明确选择“使用全局账号”时才会使用这里的凭据；独立账号缺失时不会回退到全局。</p></div></div><div class="settings-grid settings-grid--platforms">${card('全局账号','GitHub Pages',`账号：${escapeHtml(settings.github.username||'未填写')} · 分支：${escapeHtml(settings.github.branch||'gh-pages')}`,platformSecretStatus(settings.credentials.github_token),'github')}${card('全局账号','Cloudflare Pages',`账号 ID：${settings.cloudflare.account_id?'已填写':'未填写'} · 分支：${escapeHtml(settings.cloudflare.branch||'main')}`,platformSecretStatus(settings.credentials.cloudflare_token),'cloudflare')}${card('全局账号','Notion',settings.notion.enabled?'可供明确选择全局账号的站点同步。':'全局 Notion 账号未启用。',platformSecretStatus(settings.credentials.notion_token),'notion')}${card('全局设置','npm 发布',`账号：${escapeHtml(settings.npm.username||'未填写')} · 通过 GitHub OIDC 发布，不保存 npm 密码或令牌。`,settings.npm.enabled?'<span class="badge succeeded">OIDC 已启用</span>':'<span class="badge pending">尚未启用</span>','npm')}</div></section>
    <section class="panel settings-panel"><div class="panel-header"><div><h3>站点独立发布账号</h3><p class="muted">账号、分支、默认线路与加密凭据集中保存在这里。发布页只选择是否使用该独立账号。</p></div></div>${siteAccounts.length?`<div class="site-account-grid">${siteAccounts.map(siteCard).join('')}</div>`:empty('尚未登记导航站')}</section>
    <section class="panel settings-panel"><div class="panel-header"><div><h3>npm 线路角色</h3><p class="muted">UNPKG、esm.sh 用于访客打开完整网页；jsDelivr 用于静态文件分发，npmmirror 用于中国大陆 npm 安装镜像。后两者不会显示为网页入口。</p></div></div><div class="cdn-summary">${platformCdnOverview(settings.npm.lines,settings.npm.primary)}</div></section>
    <section class="panel settings-panel"><div class="panel-header"><div><h3>告警通道</h3><p class="muted">任务、发布与异常优先通知 Telegram；无法投递时再使用 Bark。</p></div><button class="secondary" data-action="alert-test">发送测试告警</button></div><div class="settings-grid settings-grid--alerts">${card('主通道','Telegram',`告警名称：${escapeHtml(settings.alerts.site_name)} · Chat ID：${settings.alerts.telegram.chat_id?'已填写':'未填写'}`,platformSecretStatus(settings.credentials.telegram_token),'telegram')}${card('备用通道','Bark',settings.alerts.bark_enabled?'已启用，Telegram 无法投递时自动接管。':'当前未启用备用通知。',platformSecretStatus(settings.credentials.bark_url),'bark')}</div></section>`;
}

async function renderJobs() {
  clearTimeout(state.jobsTimer);
  const [jobs,overview]=await Promise.all([api('/api/admin/jobs'),api('/api/admin/jobs/overview')]);
  if(state.view!=='jobs')return;
  const counts=overview.counts;
  const channelBadge=(name,configured)=>`<span class="badge ${configured?'enabled':'disabled'}">${escapeHtml(name)}：${configured?'已配置':'未配置'}</span>`;
  const taskLabel=type=>type==='publish.deploy'?'永久页发布':type==='alert.send'?'发送告警':type;
  const platformResult=job=>job.type==='publish.deploy'
    ? `${publishPlatformBadge('CF',job.result?.platforms?.cloudflare)}${publishPlatformBadge('GH',job.result?.platforms?.github)}${job.result?.platforms?.npm?publishPlatformBadge('npm',job.result.platforms.npm):''}`
    : job.result?.channel?`<span class="badge succeeded">${escapeHtml(job.result.channel)} 已送达</span>`:'—';
  const rows=jobs.map(job=>{const current=Number(job.progress_current||0),total=Math.max(1,Number(job.progress_total||1)),percent=Math.min(100,Math.round(current/total*100)),detail=job.type==='alert.send'?job.payload?.title:job.type;return `<tr><td>#${job.id}<br><span class="muted">${formatTime(job.created_at)}</span></td><td><strong>${escapeHtml(taskLabel(job.type))}</strong><br><span class="muted">${escapeHtml(detail||job.type)}</span></td><td>${escapeHtml(job.site_name||'全局')}</td><td>${jobStatusBadge(job.status)}</td><td><progress class="job-progress" max="${total}" value="${current}" aria-label="进度 ${current}/${total}">${percent}%</progress><small>${current}/${total} · ${percent}%</small></td><td><div class="meta">${platformResult(job)}</div></td><td>${job.attempts}/${job.max_attempts}</td><td class="job-error-cell">${job.last_error?`<strong>${escapeHtml(job.error_code||'UNKNOWN')}</strong><br>${escapeHtml(job.last_error)}`:'—'}</td><td><div class="row-actions">${job.status==='failed'?`<button data-action="job-retry" data-id="${job.id}">重试</button>`:''}${job.status==='queued'?`<button data-action="job-cancel" data-id="${job.id}">取消</button>`:''}</div></td></tr>`;}).join('');
  $('#content').innerHTML=`${pageHeader('任务中心','任务持久保存在数据库中；发布失败自动退避重试，最终结果通过 Telegram 或 Bark 通知。','<button class="secondary" data-action="jobs-refresh">刷新</button><button class="primary" data-action="alert-test">测试告警</button>')}
    <div class="metric-grid"><article class="metric"><span>排队中</span><strong>${counts.queued}</strong></article><article class="metric"><span>执行中</span><strong>${counts.running}</strong></article><article class="metric"><span>24 小时完成</span><strong>${counts.succeeded_24h}</strong></article><article class="metric"><span>累计失败</span><strong>${counts.failed}</strong></article><article class="metric"><span>24 小时告警成功率</span><strong>${overview.alert_success_rate===null?'暂无数据':`${overview.alert_success_rate}%`}</strong></article></div>
    <section class="panel"><div class="panel-header"><div><h3>队列与告警通道</h3><p class="muted">执行器：${overview.worker.running?'运行中':'已停止'}${overview.worker.busy?'，正在处理任务':'，当前空闲'}；最老排队任务等待 ${Number(counts.oldest_queue_seconds||0)} 秒。</p></div><div class="channel-list">${channelBadge('Telegram',overview.channels.telegram)}${channelBadge('Bark',overview.channels.bark)}</div></div>${overview.recent_alert_error?`<div class="queue-warning" role="status"><strong>最近告警失败：</strong>${escapeHtml(overview.recent_alert_error.error_code||'UNKNOWN')} · ${escapeHtml(overview.recent_alert_error.last_error||'未知原因')} · ${formatTime(overview.recent_alert_error.finished_at)}</div>`:''}</section>
    <section class="panel"><div class="panel-header"><div><h3>最近 100 个任务</h3><p class="muted">页面每 5 秒自动更新。失败原因保留稳定错误码，便于判断凭据、限流、超时或网络问题。</p></div></div>${jobs.length?`<div class="table-wrap"><table><thead><tr><th>任务 / 创建时间</th><th>类型</th><th>站点</th><th>状态</th><th>进度</th><th>执行结果</th><th>尝试</th><th>失败原因</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('尚无任务记录')}</section>`;
  state.jobsTimer=setTimeout(()=>{if(state.view==='jobs')renderJobs().catch(error=>toast(error.message));},5000);
}
async function renderAudit() {
  const logs=await api('/api/admin/audit-logs'); $('#content').innerHTML=`${pageHeader('审计日志','记录管理员与站点 Agent 的关键操作。')}<section class="panel">${logs.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th><th>来源 IP</th></tr></thead><tbody>${logs.map(log=>`<tr><td>${formatTime(log.created_at)}</td><td>${escapeHtml(log.actor_type)}:${escapeHtml(log.actor_id)}</td><td>${escapeHtml(log.action)}</td><td>${escapeHtml(log.resource_type)} ${escapeHtml(log.resource_id)}</td><td>${escapeHtml(log.ip||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无审计记录')}</section>`;
}

async function renderSecurity() {
  const data=await api('/api/admin/security');
  $('#content').innerHTML=`${pageHeader('超级管理员安全','系统仅允许一个超级管理员；账号变更会自动撤销其他会话和未使用的 SSO 票据。','<button class="secondary" data-action="security-edit">修改账号</button><button class="danger-button" data-action="security-revoke">退出其他设备</button>')}
    <div class="metric-grid"><article class="metric"><span>管理员账号</span><strong>${escapeHtml(data.admin.username)}</strong></article><article class="metric"><span>有效会话</span><strong>${data.sessions.length}</strong></article><article class="metric"><span>密码最近变更</span><strong class="small">${escapeHtml(formatTime(data.admin.password_changed_at))}</strong></article></div>
    <section class="panel"><div class="panel-header"><h3>已登录设备</h3></div><div class="table-wrap"><table><thead><tr><th>会话</th><th>来源 IP</th><th>客户端</th><th>最后活跃</th><th>过期时间</th></tr></thead><tbody>${data.sessions.map(item=>`<tr><td>${item.current?'<span class="badge online">当前设备</span>':'<span class="badge">其他设备</span>'}</td><td>${escapeHtml(item.ip||'—')}</td><td class="session-client" title="${escapeHtml(item.user_agent||'')}">${escapeHtml(item.user_agent||'未记录')}</td><td>${formatTime(item.last_seen_at)}</td><td>${formatTime(item.expires_at)}</td></tr>`).join('')}</tbody></table></div></section>`;
}

const renderers={dashboard:renderDashboard,sites:renderSites,groups:renderGroups,nodes:renderNodes,ads:renderAds,publish:renderPublish,settings:renderSettings,jobs:renderJobs,audit:renderAudit,security:renderSecurity};
async function navigate(view,{focusTitle=true}={}){clearTimeout(state.jobsTimer);state.jobsTimer=null;state.view=renderers[view]?view:'dashboard';const pageTitle=$('#pageTitle');pageTitle.textContent=titles[state.view];$('#navCurrentLabel').textContent=titles[state.view];document.querySelectorAll('#mainNav button').forEach(button=>button.setAttribute('aria-current',button.dataset.view===state.view?'page':'false'));location.hash=state.view;$('#content').innerHTML=empty('正在加载…');try{await renderers[state.view]();}catch(error){$('#content').innerHTML=empty(error.message);toast(error.message);}if(focusTitle)pageTitle.focus({preventScroll:true});$('.sidebar').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');}

function checkboxes(name, selected, items) { const set=new Set((selected||[]).map(Number)); return `<div class="choice-grid">${items.length?items.map(item=>`<label><input type="checkbox" name="${name}" value="${item.id}" ${set.has(Number(item.id))?'checked':''}>${escapeHtml(item.name)}</label>`).join(''):'<span class="muted">暂无可选项</span>'}</div>`; }
function scopeFields(item={}){return `<label>投放范围<select name="scope_mode"><option value="global" ${item.scope_mode!=='selected'?'selected':''}>全部站点</option><option value="selected" ${item.scope_mode==='selected'?'selected':''}>指定站点或分组</option></select></label><div class="span-2"><label>指定站点</label>${checkboxes('site_ids',item.site_ids,state.sites)}</div><div class="span-2"><label>指定分组</label>${checkboxes('group_ids',item.group_ids,state.groups)}</div>`;}

function normalizeModalMarkup(body){return body.replaceAll('[a-z0-9-]','[a-z0-9\\x2d]').replaceAll('[A-Za-z0-9_.-]','[A-Za-z0-9_.\\x2d]');}
function openModal(title, body, onSubmit, eyebrow='CONFIGURATION'){
  $('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=normalizeModalMarkup(body);const dialog=$('#modal');const form=dialog.querySelector('form');const errorBox=$('#modalError');errorBox.hidden=true;dialog.querySelectorAll('[value="cancel"]').forEach(button=>{button.type='button';button.dataset.modalClose='';});dialog.querySelectorAll('[data-modal-close]').forEach(button=>{button.onclick=()=>dialog.close();});form.onsubmit=async event=>{event.preventDefault();const submitter=event.submitter;if(!submitter)return;submitter.disabled=true;errorBox.hidden=true;try{const outcome=await onSubmit(new FormData(form));dialog.close();toast(outcome?.message||'保存成功');if(outcome?.refresh!==false)await navigate(state.view);outcome?.after?.();}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;errorBox.focus();toast(error.message);submitter.disabled=false;}};dialog.showModal();setTimeout(()=>dialog.querySelector('input,select,textarea')?.focus(),0);
}
function bool(data,name){return data.get(name)==='on';} function ids(data,name){return data.getAll(name).map(Number);}

async function siteForm(item={}){openModal(item.id?'编辑导航站':'新增导航站',`<div class="form-grid"><label>站点名称<input name="name" value="${escapeHtml(item.name||'')}" required maxlength="100"></label><label>站点标识<input name="slug" value="${escapeHtml(item.slug||'')}" pattern="[a-z0-9][a-z0-9-]{1,62}" required></label><label class="span-2">前台地址<input name="public_url" type="url" value="${escapeHtml(item.public_url||'')}" required></label><label class="span-2">后台地址<input name="admin_url" type="url" value="${escapeHtml(item.admin_url||'')}" required></label><label class="checkbox-line span-2"><input name="enabled" type="checkbox" ${item.enabled!==false?'checked':''}>启用站点</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存</button></div>`,async data=>{const payload={name:data.get('name'),slug:data.get('slug'),public_url:data.get('public_url'),admin_url:data.get('admin_url'),enabled:bool(data,'enabled')};const result=await api(item.id?`/api/admin/sites/${item.id}`:'/api/admin/sites',{method:item.id?'PUT':'POST',body:payload});if(result?.credential)return{refresh:false,after:()=>credentialModal(result.credential)};return{};});}
function credentialModal(value){openModal('请立即保存站点凭据',`<p class="muted">总后台不会再次显示完整凭据。把它配置到该导航站的 Agent 环境变量中。</p><div class="credential">${escapeHtml(value)}</div><div class="modal-actions"><button type="button" class="secondary" data-copy="${escapeHtml(value)}">复制凭据</button><button value="save" class="primary">我已保存</button></div>`,async()=>({message:'凭据已确认保存'}),'ONE-TIME SECRET');}
async function policyForm(siteId){const items=await api(`/api/admin/sites/${siteId}/ad-policies`);const policies=Object.fromEntries(items.map(item=>[item.slot,item.policy]));const options=[['central_only','仅中央广告'],['central_first','中央优先，其后本地'],['mixed','中央与本地混合排序'],['local_only','仅本地广告']];openModal('配置单站广告策略',`<p class="muted">每个广告位独立决定中央广告与该导航站本地广告的关系。“混合排序”会按两端的优先级统一排序。</p><div class="form-grid">${Object.entries(adSlotLabels).map(([slot,label])=>`<label>${label}<select name="${slot}">${options.map(([value,text])=>`<option value="${value}" ${(policies[slot]||'central_first')===value?'selected':''}>${text}</option>`).join('')}</select></label>`).join('')}</div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存策略</button></div>`,data=>api(`/api/admin/sites/${siteId}/ad-policies`,{method:'PUT',body:{policies:Object.keys(adSlotLabels).map(slot=>({slot,policy:data.get(slot)}))}}));}
async function groupForm(item={}){await ensureTaxonomy();openModal(item.id?'编辑站点分组':'新增站点分组',`<div class="form-grid"><label>分组名称<input name="name" value="${escapeHtml(item.name||'')}" required></label><label>分组标识<input name="slug" value="${escapeHtml(item.slug||'')}" pattern="[a-z0-9][a-z0-9-]{1,62}" required></label><div class="span-2"><label>成员站点</label>${checkboxes('site_ids',item.site_ids,state.sites)}</div></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存</button></div>`,data=>api(item.id?`/api/admin/groups/${item.id}`:'/api/admin/groups',{method:item.id?'PUT':'POST',body:{name:data.get('name'),slug:data.get('slug'),site_ids:ids(data,'site_ids')}}));}
async function nodeForm(item={}){await ensureTaxonomy();openModal(item.id?'编辑节点':'新增节点',`<div class="form-grid"><label>测速名称<input name="speed_name" value="${escapeHtml(item.speed_name||'')}" required maxlength="80"></label><label>展示名称<input name="partner_name" value="${escapeHtml(item.partner_name||'')}" required maxlength="80"></label><label class="span-2">节点地址<input name="url" type="url" value="${escapeHtml(item.url||'')}" required maxlength="2048"></label><label>排序权重 <span class="muted">数值越大越靠前</span><input name="sort_order" type="number" min="-1000000" max="1000000" step="1" value="${Number(item.sort_order||0)}"></label>${scopeFields(item)}<label class="checkbox-line span-2"><input name="enabled" type="checkbox" ${item.enabled!==false?'checked':''}>启用节点</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存</button></div>`,data=>api(item.id?`/api/admin/nodes/${item.id}`:'/api/admin/nodes',{method:item.id?'PUT':'POST',body:{speed_name:data.get('speed_name'),partner_name:data.get('partner_name'),url:data.get('url'),sort_order:Number(data.get('sort_order')||0),scope_mode:data.get('scope_mode'),site_ids:ids(data,'site_ids'),group_ids:ids(data,'group_ids'),enabled:bool(data,'enabled')}}));}
async function adForm(item={}){await ensureTaxonomy();const sandbox=item.sandbox_options||{};openModal(item.id?'编辑广告':'新增广告',`<p class="muted">主页面执行模式的位置由代码自身决定；沙箱 iframe 才会按顶部、底部或右侧图标位置排版。</p><div class="form-grid"><label>命名空间<input name="namespace" value="${escapeHtml(item.namespace||'central:')}" required maxlength="120"></label><label>标题<input name="title" value="${escapeHtml(item.title||'')}" required maxlength="120"></label><label>类型<select name="ad_type"><option value="normal" ${item.ad_type!=='code'?'selected':''}>普通图片</option><option value="code" ${item.ad_type==='code'?'selected':''}>联盟代码</option></select></label><label>位置<select name="ad_position">${Object.keys(adSlotLabels).map(value=>`<option value="${value}" ${item.ad_position===value?'selected':''}>${escapeHtml(adSlotLabels[value])}</option>`).join('')}</select></label><label>代码加载方式<select name="render_mode"><option value="sandbox" ${item.render_mode==='sandbox'?'selected':''}>沙箱 iframe（系统按广告位置排版）</option><option value="direct" ${item.render_mode!=='sandbox'?'selected':''}>加载后复制到主页面执行（代码自行定位）</option></select></label><label>平台<select name="platform">${['all','pc','ios','non_ios','android','harmony'].map(value=>`<option ${item.platform===value?'selected':''}>${value}</option>`).join('')}</select></label><label>优先级<input name="priority" type="number" min="-1000000" max="1000000" step="1" value="${Number(item.priority||0)}"></label><label>沙箱初始高度<input name="initial_height" type="number" min="50" max="800" value="${Number(sandbox.initial_height||120)}"></label><label class="span-2">图片地址<input name="image_url" type="url" maxlength="2048" value="${escapeHtml(item.image_url||'')}"></label><label class="span-2">跳转地址<input name="target_url" type="url" maxlength="2048" value="${escapeHtml(item.target_url||'')}"></label><label class="span-2">广告说明<textarea name="description" maxlength="500">${escapeHtml(item.description||'')}</textarea></label><label class="span-2">联盟代码（只保存在总后台）<textarea name="ad_code">${escapeHtml(item.ad_code||'')}</textarea></label><label class="checkbox-line span-2"><input name="direct_confirmed" type="checkbox">我确认 Direct 模式代码可以在导航站主页面执行</label><label class="checkbox-line"><input name="auto_height" type="checkbox" ${sandbox.auto_height!==false?'checked':''}>自动调整沙箱高度</label><label class="checkbox-line"><input name="allow_popups" type="checkbox" ${sandbox.allow_popups!==false?'checked':''}>允许打开广告窗口</label><label class="checkbox-line"><input name="allow_forms" type="checkbox" ${sandbox.allow_forms===true?'checked':''}>允许提交表单</label>${scopeFields(item)}<label class="checkbox-line span-2"><input name="enabled" type="checkbox" ${item.enabled!==false?'checked':''}>启用广告</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存</button></div>`,data=>{const adType=data.get('ad_type'),mode=data.get('render_mode');if(adType==='code'&&mode==='direct'&&!bool(data,'direct_confirmed'))throw new Error('Direct 模式必须确认联盟代码可以在主页面执行');return api(item.id?`/api/admin/ads/${item.id}`:'/api/admin/ads',{method:item.id?'PUT':'POST',body:{namespace:data.get('namespace'),title:data.get('title'),ad_type:adType,ad_position:data.get('ad_position'),platform:data.get('platform'),render_mode:mode,sandbox_options:{initial_height:Number(data.get('initial_height')||120),auto_height:bool(data,'auto_height'),allow_popups:bool(data,'allow_popups'),allow_forms:bool(data,'allow_forms')},priority:Number(data.get('priority')),image_url:data.get('image_url'),target_url:data.get('target_url'),description:data.get('description'),ad_code:data.get('ad_code'),scope_mode:data.get('scope_mode'),site_ids:ids(data,'site_ids'),group_ids:ids(data,'group_ids'),enabled:bool(data,'enabled')}});});}
async function adEdgeForm(item={}){await ensureTaxonomy();openModal(item.id?'编辑广告 API':'新建广告 API',`<p class="muted">系统会创建或更新独立 Worker、写入内部密钥并绑定自定义域名。Token 仅加密保存在总后台。</p><div class="form-grid"><label>配置名称<input name="name" value="${escapeHtml(item.name||'中央广告 API')}" required maxlength="100"></label><label>广告 API 域名<input name="hostname" value="${escapeHtml(item.hostname||'')}" placeholder="ad.example.com" required></label><label>Cloudflare Account ID<input name="account_id" value="${escapeHtml(item.account_id||'')}" required></label><label>Worker 名称<input name="worker_name" value="${escapeHtml(item.worker_name||'webring-ad-edge-main')}" pattern="[a-z0-9][a-z0-9-]{0,62}" required></label><label class="span-2">Cloudflare API Token<input name="api_token" type="password" autocomplete="new-password" placeholder="${item.token_configured?'已配置，留空则保留':'首次创建必须填写'}"></label><label class="checkbox-line span-2"><input name="is_default" type="checkbox" ${item.is_default?'checked':''}>设为默认中央广告 API</label><div class="span-2"><label>单独分配导航站</label>${checkboxes('site_ids',item.site_ids,state.sites)}</div><div class="span-2"><label>分配站点分组</label>${checkboxes('group_ids',item.group_ids,state.groups)}</div><label class="checkbox-line span-2"><input name="enabled" type="checkbox" ${item.enabled!==false?'checked':''}>启用广告 API</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存配置</button></div>`,data=>api(item.id?`/api/admin/ad-edge-profiles/${item.id}`:'/api/admin/ad-edge-profiles',{method:item.id?'PUT':'POST',body:{name:data.get('name'),hostname:data.get('hostname'),account_id:data.get('account_id'),worker_name:data.get('worker_name'),api_token:data.get('api_token'),is_default:bool(data,'is_default'),site_ids:ids(data,'site_ids'),group_ids:ids(data,'group_ids'),enabled:bool(data,'enabled')}}));}
function platformModeOptions(mode){return [['disabled','不启用'],['global','使用全局账号'],['site','使用本站独立账号']].map(([value,label])=>`<option value="${value}" ${mode===value?'selected':''}>${label}</option>`).join('');}
function siteSecretPlaceholder(account){return account?.credential?.configured?`已配置${account.credential.hint?` ${account.credential.hint}`:''}，留空则保留`:'尚未配置本站凭据';}
async function sitePlatformSettingsForm(siteId){
  const item=await api(`/api/admin/sites/${siteId}/publish`),accounts=item.platform_accounts||{},site=state.sites.find(value=>Number(value.id)===Number(siteId));
  const account=name=>accounts[name]||{settings:{},credential:{}};
  const npmSettings=account('npm').settings||{},npmLines=npmSettings.lines?.length?npmSettings.lines:['unpkg','esm'],npmPrimary=npmEntryPrimary(npmLines,npmSettings.primary||'')||'unpkg';
  openModal(`独立发布账号 · ${site?.name||`#${siteId}`}`,`<p class="muted">这里只管理该站点自己的平台账号。密钥留空会保留原值；发布页中的“本站独立账号”选择不会再要求重复填写。</p><div class="platform-account-stack">
    <section class="platform-account-card"><header><div><strong>Cloudflare Pages</strong><span>该站点独立 Cloudflare 账号</span></div></header><div class="form-grid"><label>Account ID<input name="cloudflare_account_id" value="${escapeHtml(account('cloudflare').settings.account_id||'')}"></label><label>发布分支<input name="cloudflare_branch" value="${escapeHtml(account('cloudflare').settings.branch||'main')}"></label><label class="span-2">API Token<input name="cloudflare_token" type="password" autocomplete="new-password" placeholder="${escapeHtml(siteSecretPlaceholder(account('cloudflare')))}"></label><label class="checkbox-line span-2"><input name="clear_cloudflare_token" type="checkbox">清除本站 Token</label></div></section>
    <section class="platform-account-card"><header><div><strong>GitHub Pages</strong><span>该站点独立 GitHub 账号</span></div></header><div class="form-grid"><label>用户名 / 组织<input name="github_username" value="${escapeHtml(account('github').settings.username||'')}"></label><label>Pages 分支<input name="github_branch" value="${escapeHtml(account('github').settings.branch||'gh-pages')}"></label><label>OIDC 工作流<input name="github_workflow_file" value="${escapeHtml(account('github').settings.workflow_file||'publish-npm.yml')}"></label><label>Fine-grained Token<input name="github_token" type="password" autocomplete="new-password" placeholder="${escapeHtml(siteSecretPlaceholder(account('github')))}"></label><label class="checkbox-line span-2"><input name="clear_github_token" type="checkbox">清除本站 Token</label></div></section>
    <section class="platform-account-card"><header><div><strong>npm 发布</strong><span>该站点独立 npm 默认设置，不保存 npm Token</span></div></header><div class="form-grid"><label>npm 用户名<input name="npm_username" value="${escapeHtml(npmSettings.username||'')}"></label><label>Registry<input name="npm_registry" type="url" value="${escapeHtml(npmSettings.registry||'https://registry.npmjs.org')}"></label><div class="span-2"><label>账号默认线路</label>${platformCdnChoices(npmLines,npmPrimary,false).replaceAll('name="npm_lines"','name="site_npm_lines"').replaceAll('name="npm_primary"','name="site_npm_primary"')}</div></div></section>
    <section class="platform-account-card"><header><div><strong>Notion</strong><span>该站点独立 Integration</span></div></header><div class="form-grid"><label>工作区备注名称<input name="notion_workspace_label" value="${escapeHtml(account('notion').settings.workspace_label||'')}"></label><label>Integration Token<input name="notion_token" type="password" autocomplete="new-password" placeholder="${escapeHtml(siteSecretPlaceholder(account('notion')))}"></label><label class="checkbox-line span-2"><input name="clear_notion_token" type="checkbox">清除本站 Token</label></div></section>
  </div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存独立账号</button></div>`,data=>{const lines=data.getAll('site_npm_lines'),primary=data.get('site_npm_primary');if(!npmEntryPrimary(lines,primary))throw new Error('独立 npm 设置至少选择 UNPKG 或 esm.sh');const secret=(field,clear)=>bool(data,clear)?null:(String(data.get(field)||'').trim()||undefined);return api(`/api/admin/platform-settings/sites/${siteId}`,{method:'PUT',body:{platforms:{cloudflare:{settings:{account_id:data.get('cloudflare_account_id'),branch:data.get('cloudflare_branch')},secret:secret('cloudflare_token','clear_cloudflare_token')},github:{settings:{username:data.get('github_username'),branch:data.get('github_branch'),workflow_file:data.get('github_workflow_file')},secret:secret('github_token','clear_github_token')},npm:{settings:{username:data.get('npm_username'),registry:data.get('npm_registry'),lines,primary}},notion:{settings:{workspace_label:data.get('notion_workspace_label')},secret:secret('notion_token','clear_notion_token')}}}});});
}
async function publishForm(siteId){
  const item=await api(`/api/admin/sites/${siteId}/publish`),page=item.payload||{},accounts=item.platform_accounts||{};
  const selected=item.npm_cdn_lines||[],primary=npmEntryPrimary(selected,item.npm_primary_cdn||'');
  const weights={cloudflare:500,github:400,notion:300,'npm:unpkg':200,'npm:esm':100,...(item.publish_link_weights||{})};
  const account=name=>accounts[name]||{mode:'disabled',settings:{},credential:{}};
  openModal('配置永久发布页',`<p class="muted">这里只选择平台账号来源并配置该发布页的资源。独立账号内容请前往“平台与告警设置”统一管理；系统不会自动回退到全局账号或其他账号。</p><div class="platform-account-stack">
    <section class="platform-account-card"><header><div><strong>Cloudflare Pages</strong><span>项目与域名始终属于当前站点</span></div><select name="cloudflare_mode" aria-label="Cloudflare 账号来源">${platformModeOptions(account('cloudflare').mode)}</select></header><div class="form-grid"><label>自定义永久发布域名<input name="permanent_url" type="url" value="${escapeHtml(item.permanent_url||'')}" placeholder="https://go.example.com"></label><label>Pages 项目名<input name="cloudflare_project" value="${escapeHtml(item.cloudflare_project||'')}" placeholder="publish-project" pattern="[a-z0-9][a-z0-9-]{0,62}"></label></div></section>
    <section class="platform-account-card"><header><div><strong>GitHub Pages</strong><span>仓库与 Pages 地址始终属于当前站点</span></div><select name="github_mode" aria-label="GitHub 账号来源">${platformModeOptions(account('github').mode)}</select></header><div class="form-grid"><label>GitHub Pages 地址<input name="github_pages_url" type="url" value="${escapeHtml(item.github_pages_url||'')}" placeholder="https://owner.github.io/repository/"></label><label>GitHub 仓库<input name="github_repo" value="${escapeHtml(item.github_repo||'')}" placeholder="owner/repository" pattern="[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"></label></div></section>
    <section class="platform-account-card"><header><div><strong>npm 发布页</strong><span>长期发布继续使用 GitHub Trusted Publisher / OIDC</span></div><select name="npm_mode" aria-label="npm 设置来源">${platformModeOptions(account('npm').mode)}</select></header><div class="form-grid"><label class="span-2">npm 包名<input name="npm_package_name" value="${escapeHtml(item.npm_package_name||'')}" placeholder="link-status-page" pattern="(?:@[a-z0-9][a-z0-9._-]{0,63}/)?[a-z0-9][a-z0-9._-]{0,119}"></label><label>线路来源<select name="npm_cdn_mode"><option value="inherit" ${item.npm_cdn_mode!=='custom'?'selected':''}>跟随所选账号设置</option><option value="custom" ${item.npm_cdn_mode==='custom'?'selected':''}>仅此发布页自定义</option></select></label><div><label>发布页自定义线路</label>${platformCdnChoices(selected,primary)}</div></div></section>
    <section class="platform-account-card"><header><div><strong>Notion 发布页</strong><span>公开地址与自动同步页面始终属于当前站点</span></div><select name="notion_mode" aria-label="Notion 账号来源">${platformModeOptions(account('notion').mode)}</select></header><div class="form-grid"><label>Notion 公开地址<input name="notion_public_url" type="url" value="${escapeHtml(item.notion_public_url||'')}" placeholder="https://workspace.notion.site/page"></label><label>Notion 页面 ID<input name="notion_page_id" value="${escapeHtml(item.notion_page_id||'')}" placeholder="32 位页面 ID"></label><label class="checkbox-line span-2"><input name="notion_sync_enabled" type="checkbox" ${item.notion_sync_enabled?'checked':''}>自动同步入口与节点到 Notion</label></div></section>
  </div><section class="platform-account-card publish-weight-card"><header><div><strong>导航站发布页排序</strong><span>数值越大越靠前；导航站自有发布页使用自己的权重参与同一排序。</span></div></header><div class="publish-weight-grid"><label>Cloudflare<input name="publish_weight_cloudflare" type="number" min="-1000000" max="1000000" step="1" value="${Number(weights.cloudflare)}"></label><label>GitHub Pages<input name="publish_weight_github" type="number" min="-1000000" max="1000000" step="1" value="${Number(weights.github)}"></label><label>Notion<input name="publish_weight_notion" type="number" min="-1000000" max="1000000" step="1" value="${Number(weights.notion)}"></label><label>UNPKG<input name="publish_weight_npm_unpkg" type="number" min="-1000000" max="1000000" step="1" value="${Number(weights['npm:unpkg'])}"></label><label>esm.sh<input name="publish_weight_npm_esm" type="number" min="-1000000" max="1000000" step="1" value="${Number(weights['npm:esm'])}"></label></div></section><div class="form-grid publish-content-fields"><label class="span-2">防失联邮箱<input name="contact_email" type="email" value="${escapeHtml(item.contact_email||'')}" placeholder="admin@example.com"></label><label class="span-2">Logo 地址<input name="logo_url" type="url" value="${escapeHtml(page.logo_url||'')}" placeholder="https://example.com/logo.png"></label><label class="span-2">页面标题<input name="page_title" maxlength="120" value="${escapeHtml(page.page_title||'')}" placeholder="留空时使用网站名称"></label><label class="span-2">页面说明<textarea name="description" maxlength="300">${escapeHtml(page.description||'')}</textarea></label><label class="span-2">临时公告<textarea name="announcement" maxlength="300">${escapeHtml(page.announcement||'')}</textarea></label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存配置</button></div>`,data=>{
    const modes=Object.fromEntries(['cloudflare','github','npm','notion'].map(name=>[name,data.get(`${name}_mode`)]));const npmMode=data.get('npm_cdn_mode'),lines=data.getAll('npm_lines'),selectedPrimary=data.get('npm_primary'),notionSyncEnabled=bool(data,'notion_sync_enabled');
    if(modes.npm!=='disabled'&&npmMode==='custom'&&!npmEntryPrimary(lines,selectedPrimary))throw new Error('npm 自定义线路至少选择 UNPKG 或 esm.sh');if(modes.npm!=='disabled'&&modes.github==='disabled')throw new Error('npm OIDC 发布需要同时启用 GitHub');if(notionSyncEnabled&&modes.notion==='disabled')throw new Error('启用 Notion 自动同步前请先启用 Notion');
    return api(`/api/admin/sites/${siteId}/publish`,{method:'PUT',body:{permanent_url:data.get('permanent_url'),github_pages_url:data.get('github_pages_url'),github_repo:data.get('github_repo'),cloudflare_project:data.get('cloudflare_project'),notion_enabled:modes.notion!=='disabled',notion_sync_enabled:notionSyncEnabled,notion_page_id:data.get('notion_page_id'),notion_public_url:data.get('notion_public_url'),npm_enabled:modes.npm!=='disabled',npm_package_name:data.get('npm_package_name'),npm_cdn_mode:npmMode,npm_cdn_lines:lines,npm_primary_cdn:selectedPrimary,publish_link_weights:{cloudflare:Number(data.get('publish_weight_cloudflare')),github:Number(data.get('publish_weight_github')),notion:Number(data.get('publish_weight_notion')),'npm:unpkg':Number(data.get('publish_weight_npm_unpkg')),'npm:esm':Number(data.get('publish_weight_npm_esm'))},contact_email:data.get('contact_email'),platforms:Object.fromEntries(Object.entries(modes).map(([name,mode])=>[name,{mode}])),payload:{logo_url:data.get('logo_url'),page_title:data.get('page_title'),description:data.get('description'),announcement:data.get('announcement'),entries:Array.isArray(page.entries)?page.entries:[]}}});
  });
}

function npmTrustedPublisherGuide(siteId,guide={}){
  const copyRow=(label,value)=>`<div><dt>${escapeHtml(label)}</dt><dd><code>${escapeHtml(value||'—')}</code>${value?`<button type="button" class="ghost compact-copy" data-copy="${escapeHtml(value)}">复制</button>`:''}</dd></div>`;
  openModal('首次发布成功：完成 npm 人工设置',`<div class="guide-intro"><strong>包已经创建成功，但自动发布尚未启用</strong><p>请在 npm 官网为这个包配置 Trusted Publisher。完成并验证 OIDC 后，再撤销本次使用的短效 Granular Token。</p></div><ol class="instruction-steps"><li>点击下方“打开 npm 包设置”，登录 npm 后进入 <strong>Settings → Trusted publishing</strong>。</li><li>选择 <strong>GitHub Actions</strong>，严格填写以下信息。</li></ol><dl class="instruction-list">${copyRow('GitHub 用户或组织',guide.organization)}${copyRow('仓库名称',guide.repository)}${copyRow('Workflow 文件名',guide.workflow_file||'publish-npm.yml')}${copyRow('Environment',guide.environment||'留空')}${copyRow('Allowed actions',guide.allowed_action||'npm publish')}</dl><ol class="instruction-steps" start="3"><li><strong>Environment 保持空白</strong>，并开启允许直接 <code>npm publish</code>。</li><li>保存后回到总后台，点击“已完成设置，验证 OIDC”。系统会发布一个新版本；只有新版本成功才算配置完成。</li><li>验证成功后，立即到 npm 的 Access Tokens 页面撤销本次短效 Token。</li></ol><div class="modal-actions">${safeUrl(guide.package_settings_url)?`<a class="secondary button-link" href="${escapeHtml(guide.package_settings_url)}" target="_blank" rel="noopener">打开 npm 包设置</a>`:''}<button type="button" class="ghost" data-modal-close>稍后处理</button><button class="primary" value="verify">已完成设置，验证 OIDC</button></div>`,async()=>{await api(`/api/admin/sites/${siteId}/publish/jobs`,{method:'POST'});return{message:'OIDC 验证任务已加入队列，请在发布页或任务中心查看结果'};},'NPM TRUSTED PUBLISHER');
}
function npmBootstrapForm(siteId,packageName){
  openModal('npm 首次发布',`<div class="guide-intro"><strong>仅用于创建 ${escapeHtml(packageName||'这个 npm 包')}</strong><p>请使用有效期尽可能短、仅授权该包且允许绕过 2FA 的 Granular Token。Token 只随本次请求进入发布子进程，不保存到数据库、日志或任务队列。</p></div><div class="form-grid"><label class="span-2">短效 Granular Token<input name="token" type="password" autocomplete="new-password" minlength="20" maxlength="500" required placeholder="npm_…"></label><p class="field-help span-2">发布成功后系统会立即显示 npm 官网 Trusted Publisher 的精确填写内容。</p><label class="checkbox-line span-2"><input name="confirmed" type="checkbox" required>我确认此 Token 仅用于首次发布，并会在 OIDC 验证成功后立即撤销</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="publish">确认并首次发布</button></div>`,async data=>{if(!bool(data,'confirmed'))throw new Error('请先确认一次性 Token 使用规则');const result=await api(`/api/admin/sites/${siteId}/publish/npm/bootstrap`,{method:'POST',body:{token:String(data.get('token')||''),confirmed:true}});return{message:'npm 首次发布成功，请继续完成官网设置',refresh:false,after:()=>npmTrustedPublisherGuide(siteId,result.instructions||{})};},'ONE-TIME NPM PUBLISH');
}
function platformSettingsForm(){api('/api/admin/platform-settings').then(settings=>{const lineChoices=platformCdnChoices(settings.npm.lines,settings.npm.primary);openModal('编辑平台与告警设置',`<p class="muted">留空的密钥字段会保留原值。Notion Token 只用于同步已授权页面；公开发布仍需在 Notion 的 Publish 页面中手动开启一次。</p><div class="form-grid"><label class="checkbox-line span-2"><input name="github_enabled" type="checkbox" ${settings.github.enabled?'checked':''}>启用 GitHub Pages 发布</label><label>GitHub 用户名<input name="github_username" value="${escapeHtml(settings.github.username||'')}" placeholder="octocat"></label><label>GitHub 分支<input name="github_branch" value="${escapeHtml(settings.github.branch||'gh-pages')}" required></label><label class="span-2">GitHub Personal Access Token<input name="github_token" type="password" autocomplete="new-password" placeholder="${settings.credentials.github_token?.configured?'已配置，留空则保留':''}"></label><label class="checkbox-line span-2"><input name="clear_github_token" type="checkbox">清除 GitHub Token</label><label class="checkbox-line span-2"><input name="cloudflare_enabled" type="checkbox" ${settings.cloudflare.enabled?'checked':''}>启用 Cloudflare Pages 发布</label><label>Cloudflare Account ID<input name="cloudflare_account_id" value="${escapeHtml(settings.cloudflare.account_id||'')}" placeholder="Account ID"></label><label>Cloudflare 分支<input name="cloudflare_branch" value="${escapeHtml(settings.cloudflare.branch||'main')}" required></label><label class="span-2">Cloudflare API Token<input name="cloudflare_token" type="password" autocomplete="new-password" placeholder="${settings.credentials.cloudflare_token?.configured?'已配置，留空则保留':''}"></label><label class="checkbox-line span-2"><input name="clear_cloudflare_token" type="checkbox">清除 Cloudflare Token</label><label class="checkbox-line span-2"><input name="notion_enabled" type="checkbox" ${settings.notion.enabled?'checked':''}>允许 Notion 自动同步</label><label class="span-2">Notion Integration Token<input name="notion_token" type="password" autocomplete="new-password" placeholder="${settings.credentials.notion_token?.configured?'已配置，留空则保留':''}"></label><label class="checkbox-line span-2"><input name="clear_notion_token" type="checkbox">清除 Notion Token</label><label class="checkbox-line span-2"><input name="npm_enabled" type="checkbox" ${settings.npm.enabled?'checked':''}>启用 npm OIDC 发布</label><label>npm 用户名<input name="npm_username" value="${escapeHtml(settings.npm.username||'')}" placeholder="your-npm-user"></label><label>npm Registry<input name="npm_registry" type="url" value="${escapeHtml(settings.npm.registry||'https://registry.npmjs.org')}" required></label><div class="span-2"><label>npm 线路 <span class="muted">至少选择 UNPKG 或 esm.sh 作为网页入口</span></label>${lineChoices}</div><label class="span-2">告警网站名称<input name="alert_site_name" value="${escapeHtml(settings.alerts.site_name||'总后台告警')}" required></label><label class="checkbox-line"><input name="telegram_enabled" type="checkbox" ${settings.alerts.telegram_enabled?'checked':''}>启用 Telegram</label><label>Telegram Chat ID<input name="telegram_chat_id" value="${escapeHtml(settings.alerts.telegram.chat_id||'')}" placeholder="数字 Chat ID"></label><label class="span-2">Telegram Bot Token<input name="telegram_token" type="password" autocomplete="new-password" placeholder="${settings.credentials.telegram_token?.configured?'已配置，留空则保留':''}"></label><label class="checkbox-line span-2"><input name="clear_telegram_token" type="checkbox">清除 Telegram Bot Token</label><label class="checkbox-line span-2"><input name="bark_enabled" type="checkbox" ${settings.alerts.bark_enabled?'checked':''}>启用 Bark 备用告警</label><label class="span-2">Bark URL<input name="bark_url" type="password" autocomplete="new-password" placeholder="${settings.credentials.bark_url?.configured?'已配置，留空则保留':'https://api.day.app/key'}"></label><label class="checkbox-line span-2"><input name="clear_bark_url" type="checkbox">清除 Bark URL</label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存平台设置</button></div>`,data=>{const lines=data.getAll('npm_lines'),npmEnabled=bool(data,'npm_enabled'),primary=data.get('npm_primary');if(npmEnabled&&!lines.length)throw new Error('请至少选择一条 npm 分发线路');if(npmEnabled&&!npmEntryPrimary(lines,primary))throw new Error('至少选择 UNPKG 或 esm.sh 作为网页入口');const secret=(field,clear)=>bool(data,clear)?null:(String(data.get(field)||'').trim()||undefined);return api('/api/admin/platform-settings',{method:'PUT',body:{github:{enabled:bool(data,'github_enabled'),username:data.get('github_username'),branch:data.get('github_branch')},cloudflare:{enabled:bool(data,'cloudflare_enabled'),account_id:data.get('cloudflare_account_id'),branch:data.get('cloudflare_branch')},notion:{enabled:bool(data,'notion_enabled')},npm:{enabled:npmEnabled,username:data.get('npm_username'),registry:data.get('npm_registry'),lines,primary},alerts:{site_name:data.get('alert_site_name'),telegram_enabled:bool(data,'telegram_enabled'),telegram:{chat_id:data.get('telegram_chat_id')},bark_enabled:bool(data,'bark_enabled')},secrets:{github_token:secret('github_token','clear_github_token'),cloudflare_token:secret('cloudflare_token','clear_cloudflare_token'),notion_token:secret('notion_token','clear_notion_token'),telegram_token:secret('telegram_token','clear_telegram_token'),bark_url:secret('bark_url','clear_bark_url')}}});});}).catch(error=>toast(error.message));}
function securityForm(){openModal('修改超级管理员',`<p class="muted">保存后会退出其他设备，当前设备继续保持登录。</p><div class="form-grid"><label class="span-2">管理员用户名<input name="username" value="${escapeHtml(state.user.username)}" required minlength="3" maxlength="64" autocomplete="username"></label><label class="span-2">当前密码<input name="current_password" type="password" required autocomplete="current-password"></label><label>新密码（不修改可留空）<input name="new_password" type="password" minlength="12" maxlength="200" autocomplete="new-password"></label><label>确认新密码<input name="confirm_password" type="password" minlength="12" maxlength="200" autocomplete="new-password"></label></div><div class="modal-actions"><button class="ghost" value="cancel">取消</button><button class="primary" value="save">保存账号</button></div>`,async data=>{const next=String(data.get('new_password')||'');if(next!==String(data.get('confirm_password')||''))throw new Error('两次输入的新密码不一致');const result=await api('/api/admin/security/account',{method:'PUT',body:{username:data.get('username'),current_password:data.get('current_password'),new_password:next}});state.user=result.user;state.csrf=result.csrf_token;$('#currentUser').textContent=state.user.username;return{message:'超级管理员账号已更新'};});}

document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.view){navigate(button.dataset.view);return;}if(button.dataset.viewJump){navigate(button.dataset.viewJump);return;}if(button.dataset.copy){await navigator.clipboard.writeText(button.dataset.copy);toast('已复制');return;}const action=button.dataset.action,id=Number(button.dataset.id);let loginWindow=null;try{if(action==='site-new')siteForm();if(action==='site-edit')siteForm(state.sites.find(x=>Number(x.id)===id));if(action==='site-policy'||action==='ad-site-policy')policyForm(id);if(action==='ad-site-preview')await previewSiteAds(id);if(action==='site-enter'){loginWindow=window.open('about:blank','_blank');if(loginWindow)loginWindow.opener=null;const result=await api(`/api/admin/sites/${id}/sso-ticket`,{method:'POST'});if(loginWindow)loginWindow.location.replace(result.url);else window.location.assign(result.url);}if(action==='site-rotate'){if(confirm('旧凭据会立即失效，确定轮换吗？'))credentialModal((await api(`/api/admin/sites/${id}/rotate-secret`,{method:'POST'})).credential);}if(action==='group-new')groupForm();if(action==='group-edit')groupForm(state.groups.find(x=>Number(x.id)===id));if(action==='node-new')nodeForm();if(action==='node-edit')nodeForm(state.nodes.find(x=>Number(x.id)===id));if(action==='node-delete'&&confirm('确定删除这个节点吗？')){await api(`/api/admin/nodes/${id}`,{method:'DELETE'});toast('节点已删除');navigate('nodes');}if(action==='ad-new')adForm();if(action==='ad-edit')adForm(state.ads.find(x=>Number(x.id)===id));if(action==='ad-delete'&&confirm('确定删除这个广告吗？')){await api(`/api/admin/ads/${id}`,{method:'DELETE'});toast('广告已删除');navigate('ads');}if(action==='publish-preview')window.open(`/api/admin/sites/${id}/publish/preview`,'_blank','noopener');if(action==='publish-history')await publishHistory(id);if(action==='publish-edit')publishForm(id);if(action==='publish-platform-test'){button.disabled=true;try{const result=await api(`/api/admin/sites/${id}/publish/platforms/${button.dataset.provider}/test`,{method:'POST'});toast(result.message||'连接正常');}finally{button.disabled=false;}}if(action==='publish-queue'){await api(`/api/admin/sites/${id}/publish/jobs`,{method:'POST'});toast('任务已加入队列');navigate('publish');}if(action==='publish-retry'){await api(`/api/admin/jobs/${id}/retry`,{method:'POST'});$('#modal').close();toast('失败平台已重新加入队列');navigate('publish');}if(action==='jobs-refresh')await navigate('jobs');if(action==='alert-test'){await api('/api/admin/alerts/test',{method:'POST'});toast('告警测试已加入队列');await navigate('jobs');}if(action==='job-retry'){await api(`/api/admin/jobs/${id}/retry`,{method:'POST'});toast('任务已重新加入队列');navigate('jobs');}if(action==='job-cancel'&&confirm('确定取消这个尚未开始的任务吗？')){await api(`/api/admin/jobs/${id}/cancel`,{method:'POST'});toast('任务已取消');navigate('jobs');}if(action==='security-edit')securityForm();if(action==='security-revoke'&&confirm('确定退出除当前设备外的所有管理会话吗？')){const result=await api('/api/admin/security/revoke-sessions',{method:'POST'});toast(`已退出 ${result.sessions_revoked} 个其他会话`);navigate('security');}}catch(error){if(loginWindow&&!loginWindow.closed)loginWindow.close();toast(error.message);}});
document.addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button)return;const action=button.dataset.action;if(!['platform-edit','platform-test','site-platform-edit','site-platform-test'].includes(action))return;try{if(action==='platform-edit'){platformSettingsForm();return;}if(action==='site-platform-edit'){sitePlatformSettingsForm(Number(button.dataset.id));return;}const provider=button.dataset.provider;button.disabled=true;try{const path=action==='site-platform-test'?`/api/admin/platform-settings/sites/${Number(button.dataset.id)}/test/${provider}`:`/api/admin/platform-settings/test/${provider}`;const result=await api(path,{method:'POST'});toast(result.message||`${provider} 连接成功`);}finally{button.disabled=false;}}catch(error){toast(error.message);}});

document.addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button)return;const id=Number(button.dataset.id);try{if(button.dataset.action==='npm-bootstrap'){npmBootstrapForm(id,button.dataset.package);return;}if(button.dataset.action==='npm-oidc-verify'){const item=await api(`/api/admin/sites/${id}/publish`);npmTrustedPublisherGuide(id,item.npm_bootstrap?.instructions||{});}}catch(error){toast(error.message);}});

document.addEventListener('click',async event=>{
  const button=event.target.closest('button[data-action]');
  if(!button)return;
  const action=button.dataset.action;
  if(!['ad-edge-new','ad-edge-edit','ad-edge-deploy'].includes(action))return;
  const id=Number(button.dataset.id);
  try{
    if(action==='ad-edge-new'){await adEdgeForm();return;}
    if(action==='ad-edge-edit'){await adEdgeForm(state.adEdgeProfiles.find(item=>Number(item.id)===id)||{});return;}
    if(action==='ad-edge-deploy'){
      if(!confirm('将创建或更新 Cloudflare Worker、写入密钥并绑定广告 API 域名，确定继续吗？'))return;
      button.disabled=true;
      try{
        const result=await api(`/api/admin/ad-edge-profiles/${id}/deploy`,{method:'POST'});
        toast(result.health_status==='healthy'?'广告 API 已部署并通过健康检查':'广告 API 已部署，域名证书或路由仍在生效中');
        await navigate('ads');
      }finally{button.disabled=false;}
    }
  }catch(error){toast(error.message);}
});

$('#navToggle').addEventListener('click',()=>{const nav=$('#mainNav');const open=nav.classList.toggle('open');$('#navToggle').setAttribute('aria-expanded',String(open));});
$('#loginForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter,error=$('#loginError');button.disabled=true;error.hidden=true;try{const form=new FormData(event.currentTarget);const result=await api('/api/auth/login',{method:'POST',body:{username:form.get('username'),password:form.get('password')}});state.user=result.user;state.csrf=result.csrf_token;showApp();navigate(location.hash.slice(1)||'dashboard');}catch(err){error.textContent=err.message;error.hidden=false;}finally{button.disabled=false;}});
$('#logoutButton').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'});}finally{showLogin();}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(state.user&&view!==state.view)navigate(view);});

(async()=>{try{const result=await api('/api/auth/me');state.user=result.user;state.csrf=result.csrf_token;showApp();await navigate(location.hash.slice(1)||'dashboard',{focusTitle:false});}catch{showLogin();}})();
